🎯 StudentController完成版 <pre><code>package com.example.demo.controller;

import com.example.demo.entity.Student;
import com.example.demo.service.StudentService;
import com.example.demo.exception.StudentNotFoundException;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.util.List;
import java.util.Optional;

@RestController
@RequestMapping("/api/students")
@CrossOrigin(origins = "*")
public class StudentController {

    @Autowired
    private StudentService studentService;

    /**
     * 全学生取得 API
     */
    @GetMapping
    public ResponseEntity&lt;List&lt;Student&gt;&gt; getAllStudents() {
        List&lt;Student&gt; students = studentService.findAll();
        return ResponseEntity.ok(students);
    }

    /**
     * 特定学生取得 API
     */
    @GetMapping("/{id}")
    public ResponseEntity&lt;Student&gt; getStudentById(@PathVariable Long id) {
        validateId(id);
        Optional&lt;Student&gt; student = studentService.findById(id);
        return student.map(ResponseEntity::ok)
                     .orElseThrow(() -&gt; new StudentNotFoundException(id));
    }

    /**
     * 学生作成 API
     */
    @PostMapping
    public ResponseEntity&lt;Student&gt; createStudent(@RequestBody Student student) {
        validateStudent(student);
        Student createdStudent = studentService.save(student);
        return ResponseEntity.status(HttpStatus.CREATED).body(createdStudent);
    }

    /**
     * 学生更新 API
     */
    @PutMapping("/{id}")
    public ResponseEntity&lt;Student&gt; updateStudent(@PathVariable Long id, @RequestBody Student student) {
        validateId(id);

        // 存在確認
        if (!studentService.findById(id).isPresent()) {
            throw new StudentNotFoundException(id);
        }

        student.setId(id);
        validateStudent(student);
        Student updatedStudent = studentService.save(student);
        return ResponseEntity.ok(updatedStudent);
    }

    /**
     * 学生削除 API
     */
    @DeleteMapping("/{id}")
    public ResponseEntity&lt;Void&gt; deleteStudent(@PathVariable Long id) {
        validateId(id);

        // 存在確認
        if (!studentService.findById(id).isPresent()) {
            throw new StudentNotFoundException(id);
        }

        studentService.deleteById(id);
        return ResponseEntity.noContent().build();
    }

    /**
     * ID バリデーション
     */
    private void validateId(Long id) {
        if (id == null || id &lt;= 0) {
            throw new IllegalArgumentException("IDは1以上の数値である必要があります");
        }
    }

    /**
     * 学生データ バリデーション
     */
    private void validateStudent(Student student) {
        if (student.getName() == null || student.getName().trim().isEmpty()) {
            throw new IllegalArgumentException("学生名は必須です");
        }

        if (student.getEmail() == null || !isValidEmail(student.getEmail())) {
            throw new IllegalArgumentException("有効なメールアドレスを入力してください");
        }

        if (student.getAge() &lt; 15 || student.getAge() &gt; 100) {
            throw new IllegalArgumentException("年齢は15歳以上100歳以下で入力してください");
        }

        if (student.getGrade() == null || student.getGrade().trim().isEmpty()) {
            throw new IllegalArgumentException("成績は必須です");
        }
    }

    /**
     * メールアドレス形式チェック
     */
    private boolean isValidEmail(String email) {
        return email.contains("@") &amp;&amp; email.contains(".") &amp;&amp; email.length() &gt; 5;
    }
}
</code></pre>

