🎯 完成版コード <pre><code>import lombok.Data;
import lombok.NoArgsConstructor;
import lombok.AllArgsConstructor;
import javax.validation.constraints.*;

@Data
@NoArgsConstructor
@AllArgsConstructor
public class StudentData {

    @NotBlank(message = "名前は必須です")&lt;br&gt;
    @Size(min = 1, max = 50, message = "名前は1文字以上50文字以下で入力してください")&lt;br&gt;
    private String name;&lt;br&gt;
    &lt;br&gt;
    @NotBlank(message = "メールアドレスは必須です")&lt;br&gt;
    @Email(message = "正しいメールアドレスを入力してください")&lt;br&gt;
    private String email;&lt;br&gt;
    &lt;br&gt;
    @NotNull(message = "年齢は必須です")&lt;br&gt;
    @Min(value = 0, message = "年齢は0歳以上で入力してください")&lt;br&gt;
    @Max(value = 150, message = "年齢は150歳以下で入力してください")&lt;br&gt;
    private Integer age;&lt;br&gt;
    &lt;br&gt;
    @NotBlank(message = "パスワードは必須です")&lt;br&gt;
    @Size(min = 8, max = 100, message = "パスワードは8文字以上100文字以下で入力してください")&lt;br&gt;
    private String password;&lt;br&gt;
    &lt;br&gt;
    @NotBlank(message = "パスワード確認は必須です")&lt;br&gt;
    private String confirmPassword;&lt;br&gt;
    &lt;br&gt;
    @AssertTrue(message = "利用規約に同意してください")&lt;br&gt;
    private Boolean agreeTerms;&lt;br&gt;
    &lt;br&gt;
    /**&lt;br&gt;
     * DTOからEntityへの変換&lt;br&gt;
     */&lt;br&gt;
    public Student toEntity() {&lt;br&gt;
        Student student = new Student();&lt;br&gt;
        student.setName(this.name);&lt;br&gt;
        student.setEmail(this.email);&lt;br&gt;
        student.setAge(this.age);&lt;br&gt;
        return student;&lt;br&gt;
    }&lt;br&gt;
    &lt;br&gt;
    /**&lt;br&gt;
     * EntityからDTOへの変換&lt;br&gt;
     */&lt;br&gt;
    public static StudentData fromEntity(Student student) {&lt;br&gt;
        StudentData data = new StudentData();&lt;br&gt;
        data.setName(student.getName());&lt;br&gt;
        data.setEmail(student.getEmail());&lt;br&gt;
        data.setAge(student.getAge());&lt;br&gt;
        data.setAgreeTerms(false);&lt;br&gt;
        return data;&lt;br&gt;
    }&lt;br&gt;
    &lt;br&gt;
    /**&lt;br&gt;
     * パスワード一致チェック&lt;br&gt;
     */&lt;br&gt;
    public boolean isPasswordMatching() {&lt;br&gt;
        if (password == null || confirmPassword == null) {&lt;br&gt;
            return false;&lt;br&gt;
        }&lt;br&gt;
        return password.equals(confirmPassword);&lt;br&gt;
    }&lt;br&gt;
}
