🏆 完成版: StudentController.java <pre><code>package com.example.demo.controller;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.validation.BindingResult;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.ModelAttribute;
import org.springframework.web.bind.annotation.PostMapping;
import javax.validation.Valid;

import com.example.demo.dto.StudentData;
import com.example.demo.repository.StudentRepository;

@Controller
public class StudentController {

    @Autowired
    private StudentRepository studentRepository;

    @GetMapping("/students/new")
    public String showForm(Model model) {
        System.out.println("新規登録フォーム画面を表示します");
        model.addAttribute("studentData", new StudentData());
        return "students/form";
    }

    @PostMapping("/students")
    public String createStudent(@Valid @ModelAttribute StudentData studentData, 
                              BindingResult bindingResult, Model model) {

        System.out.println("=== バリデーション実行 ===");
        System.out.println("受信データ: " + studentData);
        System.out.println("エラー有無: " + bindingResult.hasErrors());

        if (bindingResult.hasErrors()) {
            System.out.println("バリデーションエラーが発生しました");
            System.out.println("エラー数: " + bindingResult.getErrorCount());

            System.out.println("エラー詳細:");
            bindingResult.getAllErrors().forEach(error -&gt; 
                System.out.println("- " + error.getDefaultMessage())
            );

            System.out.println("フォーム画面に戻ります");
            return "students/form";
        }

        System.out.println("バリデーション成功!");
        System.out.println("学生データ: " + studentData);

        // Week 9.5でDB保存処理を実装予定
        System.out.println("DB保存処理は Week 9.5 で実装予定");

        return "redirect:/students";
    }
}
