Resultパターンの実用例 <pre><code>public class FileService
{
    public async Task&lt;Result&lt;string&gt;&gt; ReadFileAsync(string filePath)
    {
        try
        {
            if (string.IsNullOrWhiteSpace(filePath))
            {
                return Result&lt;string&gt;.Failure("ファイルパスが指定されていません", "INVALID_PATH");
            }

            if (!File.Exists(filePath))
            {
                return Result&lt;string&gt;.Failure($"ファイルが存在しません: {filePath}", "FILE_NOT_FOUND");
            }

            var content = await File.ReadAllTextAsync(filePath);
            return Result&lt;string&gt;.Success(content);
        }
        catch (UnauthorizedAccessException ex)
        {
            return Result&lt;string&gt;.Failure(ex, "ACCESS_DENIED");
        }
        catch (IOException ex)
        {
            return Result&lt;string&gt;.Failure(ex, "IO_ERROR");
        }
        catch (Exception ex)
        {
            return Result&lt;string&gt;.Failure(ex, "UNKNOWN_ERROR");
        }
    }

    public async Task&lt;Result&gt; WriteFileAsync(string filePath, string content)
    {
        try
        {
            if (string.IsNullOrWhiteSpace(filePath))
            {
                return Result.Failure("ファイルパスが指定されていません", "INVALID_PATH");
            }

            // ディレクトリが存在しない場合は作成
            var directory = Path.GetDirectoryName(filePath);
            if (!string.IsNullOrEmpty(directory) &amp;&amp; !Directory.Exists(directory))
            {
                Directory.CreateDirectory(directory);
            }

            await File.WriteAllTextAsync(filePath, content);
            return Result.Success();
        }
        catch (Exception ex)
        {
            return Result.Failure(ex, "WRITE_ERROR");
        }
    }
}

