Spanによる高速文字列処理 <pre><code>using System;
using System.Buffers;

public class SpanOptimizations
{
    // 従来の方法（メモリ割り当てが多い）
    public int ProcessStringTraditional(string input)
    {
        // 文字列分割で新しい配列が作成される
        var parts = input.Split(',');
        int sum = 0;

        foreach (var part in parts)
        {
            // Trimで新しい文字列が作成される
            var trimmed = part.Trim();
            if (int.TryParse(trimmed, out var number))
            {
                sum += number;
            }
        }

        return sum;
    }

    // Span&lt;T&gt;を使用した最適化版（メモリ割り当てを大幅に削減）
    public int ProcessStringWithSpan(ReadOnlySpan&lt;char&gt; input)
    {
        int sum = 0;
        int start = 0;

        for (int i = 0; i &lt;= input.Length; i++)
        {
            if (i == input.Length || input[i] == ',')
            {
                // 部分文字列を新しい文字列として作成せずに参照
                var part = input.Slice(start, i - start).Trim();

                if (int.TryParse(part, out var number))
                {
                    sum += number;
                }

                start = i + 1;
            }
        }

        return sum;
    }

    // 配列処理の最適化比較
    public void DemonstrateArrayOptimization()
    {
        var sourceData = Enumerable.Range(1, 100000).ToArray();
        var resultArray = new int[sourceData.Length];

        Console.WriteLine("=== 配列処理最適化デモ ===");

        PerformanceMeasurement.ComparePerformance(
            "Traditional array processing",
            () =&gt; ProcessArrayTraditional(sourceData),
            "Span&lt;T&gt; processing",
            () =&gt; ProcessArrayWithSpan(sourceData.AsSpan(), resultArray.AsSpan()),
            100
        );
    }

    private int[] ProcessArrayTraditional(int[] source)
    {
        var result = new int[source.Length];
        for (int i = 0; i &lt; source.Length; i++)
        {
            result[i] = source[i] * 2 + 1;
        }
        return result;
    }

    private void ProcessArrayWithSpan(ReadOnlySpan&lt;int&gt; source, Span&lt;int&gt; destination)
    {
        for (int i = 0; i &lt; source.Length; i++)
        {
            destination[i] = source[i] * 2 + 1;
        }
    }

    // StackallocとSpanの組み合わせ
    public int ProcessWithStackAlloc(ReadOnlySpan&lt;int&gt; input)
    {
        // スタックに小さなバッファを確保（ヒープ割り当てなし）
        Span&lt;int&gt; buffer = stackalloc int[256];

        int sum = 0;
        int bufferIndex = 0;

        for (int i = 0; i &lt; input.Length; i++)
        {
            if (input[i] &gt; 0)
            {
                buffer[bufferIndex++] = input[i];

                if (bufferIndex == buffer.Length)
                {
                    // バッファが満杯になったら処理
                    sum += ProcessBuffer(buffer);
                    bufferIndex = 0;
                }
            }
        }

        // 残りのデータを処理
        if (bufferIndex &gt; 0)
        {
            sum += ProcessBuffer(buffer.Slice(0, bufferIndex));
        }

        return sum;
    }

    private int ProcessBuffer(ReadOnlySpan&lt;int&gt; buffer)
    {
        int sum = 0;
        foreach (var value in buffer)
        {
            sum += value;
        }
        return sum;
    }
}

// Memory&lt;T&gt;を使用した非同期対応の高性能処理
public class MemoryOptimizations
{
    private readonly ArrayPool&lt;byte&gt; _bytePool = ArrayPool&lt;byte&gt;.Shared;

    // 非同期処理でMemory&lt;T&gt;を使用
    public async Task&lt;string&gt; ProcessLargeDataAsync(Stream dataStream)
    {
        var buffer = _bytePool.Rent(8192); // 8KB buffer

        try
        {
            var memory = buffer.AsMemory(0, 8192);
            var totalBytesRead = 0;
            int bytesRead;

            // 非同期読み込みでMemory&lt;T&gt;を使用
            while ((bytesRead = await dataStream.ReadAsync(memory.Slice(totalBytesRead))) &gt; 0)
            {
                totalBytesRead += bytesRead;

                if (totalBytesRead &gt;= memory.Length)
                {
                    // バッファが満杯の場合の処理
                    var processedData = ProcessMemorySegment(memory.Slice(0, totalBytesRead));
                    Console.WriteLine($"Processed {totalBytesRead} bytes: {processedData}");
                    totalBytesRead = 0;
                }
            }

            // 残りのデータを処理
            if (totalBytesRead &gt; 0)
            {
                var finalData = ProcessMemorySegment(memory.Slice(0, totalBytesRead));
                return finalData;
            }

            return "Processing completed";
        }
        finally
        {
            _bytePool.Return(buffer);
        }
    }

    private string ProcessMemorySegment(ReadOnlyMemory&lt;byte&gt; segment)
    {
        var span = segment.Span;

        // バイトデータの簡単な処理例
        int sum = 0;
        for (int i = 0; i &lt; span.Length; i++)
        {
            sum += span[i];
        }

        return $"Checksum: {sum}";
    }

    // 文字列処理の高速化
    public bool ValidateEmailWithSpan(ReadOnlySpan&lt;char&gt; email)
    {
        // @の位置を探す
        int atIndex = email.IndexOf('@');
        if (atIndex &lt;= 0 || atIndex == email.Length - 1)
        {
            return false;
        }

        var localPart = email.Slice(0, atIndex);
        var domainPart = email.Slice(atIndex + 1);

        // ローカル部分の検証
        if (localPart.Length == 0 || localPart.Length &gt; 64)
        {
            return false;
        }

        // ドメイン部分の検証（簡易版）
        if (domainPart.Length == 0 || domainPart.IndexOf('.') == -1)
        {
            return false;
        }

        // 禁止文字のチェック
        foreach (var ch in localPart)
        {
            if (!char.IsLetterOrDigit(ch) &amp;&amp; ch != '.' &amp;&amp; ch != '_' &amp;&amp; ch != '-')
            {
                return false;
            }
        }

        return true;
    }

    public void DemonstrateEmailValidation()
    {
        var emails = new[]
        {
            "valid@example.com",
            "user.name@domain.co.jp",
            "invalid-email",
            "@invalid.com",
            "test@domain.",
            "toolong" + new string('x', 100) + "@example.com"
        };

        Console.WriteLine("=== メール検証デモ（Span使用） ===");
        foreach (var email in emails)
        {
            bool isValid = ValidateEmailWithSpan(email.AsSpan());
            Console.WriteLine($"{email}: {(isValid ? "✅ 有効" : "❌ 無効")}");
        }
    }
}
</code></pre>

効率的な並行処理パターン <pre><code>using System;
using System.Collections.Concurrent;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;

public class AsyncOptimizations
{
    private readonly HttpClient _httpClient = new HttpClient();

    // 非効率な逐次処理
    public async Task&lt;List&lt;string&gt;&gt; DownloadSequentiallyAsync(string[] urls)
    {
        Console.WriteLine("=== 逐次ダウンロード開始 ===");
        var results = new List&lt;string&gt;();
        var stopwatch = Stopwatch.StartNew();

        foreach (var url in urls)
        {
            Console.WriteLine($"Downloading: {url}");
            try
            {
                var content = await _httpClient.GetStringAsync(url);
                var preview = content.Length &gt; 50 ? content.Substring(0, 50) + "..." : content;
                results.Add(preview);
            }
            catch (Exception ex)
            {
                results.Add($"Error: {ex.Message}");
            }
        }

        stopwatch.Stop();
        Console.WriteLine($"逐次処理完了: {stopwatch.ElapsedMilliseconds}ms");
        return results;
    }

    // 効率的な並行処理
    public async Task&lt;List&lt;string&gt;&gt; DownloadConcurrentlyAsync(string[] urls)
    {
        Console.WriteLine("=== 並行ダウンロード開始 ===");
        var stopwatch = Stopwatch.StartNew();

        var tasks = urls.Select(async url =&gt;
        {
            Console.WriteLine($"Starting download: {url}");
            try
            {
                var content = await _httpClient.GetStringAsync(url);
                var preview = content.Length &gt; 50 ? content.Substring(0, 50) + "..." : content;
                Console.WriteLine($"Completed: {url}");
                return preview;
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Failed: {url} - {ex.Message}");
                return $"Error: {ex.Message}";
            }
        });

        var results = await Task.WhenAll(tasks);

        stopwatch.Stop();
        Console.WriteLine($"並行処理完了: {stopwatch.ElapsedMilliseconds}ms");
        return results.ToList();
    }

    // 並行度制限付き処理（リソース制御）
    public async Task&lt;List&lt;string&gt;&gt; DownloadWithLimitedConcurrencyAsync(
        string[] urls, int maxConcurrency = 3)
    {
        Console.WriteLine($"=== 制限付き並行ダウンロード開始 (最大{maxConcurrency}並行) ===");
        var semaphore = new SemaphoreSlim(maxConcurrency, maxConcurrency);
        var results = new ConcurrentBag&lt;(int index, string content)&gt;();
        var stopwatch = Stopwatch.StartNew();

        var tasks = urls.Select(async (url, index) =&gt;
        {
            await semaphore.WaitAsync();
            try
            {
                Console.WriteLine($"[{index}] Starting: {url}");
                var content = await _httpClient.GetStringAsync(url);
                var preview = content.Length &gt; 50 ? content.Substring(0, 50) + "..." : content;
                results.Add((index, preview));
                Console.WriteLine($"[{index}] Completed: {url}");
            }
            catch (Exception ex)
            {
                results.Add((index, $"Error: {ex.Message}"));
                Console.WriteLine($"[{index}] Failed: {url}");
            }
            finally
            {
                semaphore.Release();
            }
        });

        await Task.WhenAll(tasks);

        stopwatch.Stop();
        Console.WriteLine($"制限付き並行処理完了: {stopwatch.ElapsedMilliseconds}ms");

        return results.OrderBy(r =&gt; r.index).Select(r =&gt; r.content).ToList();
    }

    // ValueTask&lt;T&gt;の効果的な使用（キャッシュシナリオ）
    private readonly ConcurrentDictionary&lt;string, (string data, DateTime cached)&gt; _cache = new();
    private readonly TimeSpan _cacheExpiry = TimeSpan.FromMinutes(5);

    public ValueTask&lt;string&gt; GetCachedDataAsync(string key)
    {
        // キャッシュヒットの場合は同期的に返す（ヒープ割り当てなし）
        if (_cache.TryGetValue(key, out var cached) &amp;&amp; 
            DateTime.Now - cached.cached &lt; _cacheExpiry)
        {
            Console.WriteLine($"Cache hit for: {key}");
            return new ValueTask&lt;string&gt;(cached.data);
        }

        Console.WriteLine($"Cache miss for: {key}");
        // キャッシュミスの場合のみ非同期処理
        return new ValueTask&lt;string&gt;(LoadDataAsync(key));
    }

    private async Task&lt;string&gt; LoadDataAsync(string key)
    {
        // データロード処理をシミュレート
        await Task.Delay(Random.Shared.Next(100, 500));

        var data = $"Data for {key} loaded at {DateTime.Now:HH:mm:ss.fff}";
        _cache.TryAdd(key, (data, DateTime.Now));

        Console.WriteLine($"Data loaded and cached: {key}");
        return data;
    }

    // 高性能なプロデューサー・コンシューマーパターン
    public async Task&lt;int&gt; ProcessLargeDataSetAsync&lt;T&gt;(
        IAsyncEnumerable&lt;T&gt; dataSource,
        Func&lt;T, Task&lt;string&gt;&gt; processor,
        int maxConcurrency = Environment.ProcessorCount)
    {
        var processed = 0;
        var semaphore = new SemaphoreSlim(maxConcurrency, maxConcurrency);
        var processingTasks = new List&lt;Task&gt;();

        await foreach (var item in dataSource)
        {
            await semaphore.WaitAsync();

            var task = ProcessItemAsync(item, processor, semaphore);
            processingTasks.Add(task);

            // 完了したタスクを定期的に除去（メモリ効率）
            if (processingTasks.Count &gt;= maxConcurrency * 2)
            {
                var completedTasks = processingTasks.Where(t =&gt; t.IsCompleted).ToList();
                foreach (var completedTask in completedTasks)
                {
                    processingTasks.Remove(completedTask);
                    processed++;
                }
            }
        }

        // 残りのタスクの完了を待機
        await Task.WhenAll(processingTasks);
        processed += processingTasks.Count;

        Console.WriteLine($"Total items processed: {processed}");
        return processed;
    }

    private async Task ProcessItemAsync&lt;T&gt;(
        T item, 
        Func&lt;T, Task&lt;string&gt;&gt; processor, 
        SemaphoreSlim semaphore)
    {
        try
        {
            var result = await processor(item);
            // 結果の処理（ここでは表示のみ）
            if (Random.Shared.Next(100) &lt; 5) // 5%の確率で表示
            {
                Console.WriteLine($"Processed item: {result}");
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Processing failed: {ex.Message}");
        }
        finally
        {
            semaphore.Release();
        }
    }
}

// ConfigureAwait(false)の重要性を示すデモ
public class ConfigureAwaitDemo
{
    // デッドロックが発生する可能性のあるコード
    public string DeadlockProneMethod()
    {
        // UIスレッドやASP.NETでSynchronizationContextがある場合、
        // .Result を使うとデッドロックの可能性
        return LoadDataAsync().Result; // 危険！
    }

    // 安全なライブラリコード
    public async Task&lt;string&gt; SafeLibraryMethodAsync()
    {
        // ライブラリコードではConfigureAwait(false)を使用
        var data1 = await LoadDataAsync().ConfigureAwait(false);
        var data2 = await ProcessDataAsync(data1).ConfigureAwait(false);
        return await FormatDataAsync(data2).ConfigureAwait(false);
    }

    private async Task&lt;string&gt; LoadDataAsync()
    {
        await Task.Delay(100);
        return "Raw data";
    }

    private async Task&lt;string&gt; ProcessDataAsync(string data)
    {
        await Task.Delay(100);
        return $"Processed: {data}";
    }

    private async Task&lt;string&gt; FormatDataAsync(string data)
    {
        await Task.Delay(100);
        return $"Formatted: {data}";
    }
}
</code></pre>

