    // 敵のステータス
    int enemy_hp = 40;
    int enemy_attack = 10;
    int enemy_defense = 3;

    printf("=== 戦闘開始 ===\n\n");
    printf("[勇者]    HP: %d  攻撃力: %d  防御力: %d\n", 
           player_hp, player_attack, player_defense);
    printf("[スライム] HP: %d   攻撃力: %d   防御力: %d\n\n", 
           enemy_hp, enemy_attack, enemy_defense);

    printf("--- ターン1 ---\n");

    // プレイヤーの攻撃
    int damage1 = player_attack - enemy_defense;
    if (damage1 &lt; 1) damage1 = 1;

    int old_enemy_hp = enemy_hp;
    enemy_hp = enemy_hp - damage1;

    printf("勇者の攻撃！\n");
    printf("ダメージ: %d\n", damage1);
    printf("スライムのHP: %d -&gt; %d\n\n", old_enemy_hp, enemy_hp);

    // 敵の攻撃
    int raw_damage = enemy_attack - player_defense;
    int damage2 = raw_damage;
    if (damage2 &lt; 1) damage2 = 1;

    int old_player_hp = player_hp;
    player_hp = player_hp - damage2;

    printf("スライムの攻撃！\n");
    if (raw_damage &lt; 1) {
        printf("ダメージ: %d -&gt; 1（最低保証）\n", raw_damage);
    } else {
        printf("ダメージ: %d\n", damage2);
    }
    printf("勇者のHP: %d -&gt; %d\n\n", old_player_hp, player_hp);

    // 結果
    printf("--- 結果 ---\n");
    printf("勇者のHP: %d\n", player_hp);
    printf("スライムのHP: %d\n", enemy_hp);

    return 0;
}
