battle_cmd.c の正解（自分で試してから見てください） <pre><code>#include &lt;stdio.h&gt;

int main(void) {
    int player_hp = 100;
    int player_mp = 30;
    int player_attack = 20;
    int player_defense = 10;

    int enemy_hp = 40;
    int enemy_defense = 3;

    int cmd;

    printf("=== 戦闘 ===\n");
    printf("勇者のHP: %d  MP: %d\n", player_hp, player_mp);
    printf("スライムのHP: %d\n\n", enemy_hp);

    printf("+---------------------------+\n");
    printf("|  1. 攻撃    2. 防御      |\n");
    printf("|  3. スキル  4. 逃げる    |\n");
    printf("+---------------------------+\n");
    printf("コマンド: ");

    scanf("%d", &amp;cmd);
    printf("\n");

    switch (cmd) {
        case 1: {
            // 攻撃
            int damage = player_attack - enemy_defense;
            if (damage &lt; 1) damage = 1;
            int old_hp = enemy_hp;
            enemy_hp -= damage;

            printf("勇者の攻撃！\n");
            printf("ダメージ: %d\n", damage);
            printf("スライムのHP: %d -&gt; %d\n", old_hp, enemy_hp);
            break;
        }
        case 2:
            // 防御
            printf("勇者は身を守っている！\n");
            printf("このターン、受けるダメージが減少します。\n");
            break;
        case 3:
            // スキル
            if (player_mp &gt;= 10) {
                player_mp -= 10;
                int skill_damage = (int)(player_attack * 1.5) - enemy_defense;
                if (skill_damage &lt; 1) skill_damage = 1;
                int old_hp = enemy_hp;
                enemy_hp -= skill_damage;

                printf("勇者のパワースラッシュ！\n");
                printf("MP: %d -&gt; %d\n", player_mp + 10, player_mp);
                printf("ダメージ: %d\n", skill_damage);
                printf("スライムのHP: %d -&gt; %d\n", old_hp, enemy_hp);
            } else {
                printf("MPが足りません！\n");
            }
            break;
        case 4:
            // 逃げる
            printf("勇者は逃げ出した！\n");
            printf("戦闘から離脱しました。\n");
            break;
        default:
            printf("無効なコマンドです。もう一度入力してください。\n");
            break;
    }

    return 0;
}
</code></pre>

