battle_v1.c の正解（自分で試してから見てください） <pre><code>/*
 * ダンジョン探索 RPG - 戦闘システム (Week 1)
 */

#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;time.h&gt;

// === グローバル変数 ===
int player_hp, player_max_hp;
int player_mp, player_max_mp;
int player_attack, player_defense;
int player_level, player_exp;

int enemy_hp, enemy_max_hp;
int enemy_attack, enemy_defense;
int enemy_exp_reward;
int enemy_type;

const char* enemy_names[] = {"スライム", "ゴブリン", "コウモリ"};

// === プロトタイプ宣言 ===
void init_player(void);
void init_enemy(void);
void show_title(void);
void show_status(void);
void show_menu(void);
int calc_damage(int attack, int defense, int *is_crit);
void do_player_attack(void);
void do_player_defend(int *defending);
void do_player_skill(void);
int try_escape(void);
void do_enemy_turn(int defending);
void check_level_up(void);

// === 初期化 ===
void init_player(void) {
    player_level = 1;
    player_exp = 0;
    player_max_hp = 100;
    player_hp = player_max_hp;
    player_max_mp = 30;
    player_mp = player_max_mp;
    player_attack = 20;
    player_defense = 10;
}

void init_enemy(void) {
    enemy_type = rand() % 3;

    switch (enemy_type) {
        case 0:
            enemy_max_hp = 40 + rand() % 21 - 10;
            enemy_attack = 10;
            enemy_defense = 3;
            enemy_exp_reward = 20;
            break;
        case 1:
            enemy_max_hp = 60 + rand() % 21 - 10;
            enemy_attack = 15;
            enemy_defense = 5;
            enemy_exp_reward = 35;
            break;
        case 2:
            enemy_max_hp = 30 + rand() % 21 - 10;
            enemy_attack = 12;
            enemy_defense = 2;
            enemy_exp_reward = 25;
            break;
    }
    enemy_hp = enemy_max_hp;
}

// === 表示 ===
void show_title(void) {
    printf("\n");
    printf("+========================================+\n");
    printf("|       ダンジョン探索 RPG - Week 1      |\n");
    printf("+========================================+\n");
    printf("\n  あなたは勇者です...\n");
    printf("  （Enterキーでスタート）\n");
}

void show_status(void) {
    printf("\n");
    printf("+----------------------------------------+\n");
    printf("|  [%s]\n", enemy_names[enemy_type]);
    printf("|  HP: %3d / %3d\n", enemy_hp, enemy_max_hp);
    printf("+----------------------------------------+\n");
    printf("|  [勇者] Lv.%d\n", player_level);
    printf("|  HP: %3d / %3d    MP: %2d / %2d\n",
           player_hp, player_max_hp, player_mp, player_max_mp);
    printf("+----------------------------------------+\n");
}

void show_menu(void) {
    printf("\n");
    printf("  +---------------------------+\n");
    printf("  |  1. 攻撃    2. 防御      |\n");
    printf("  |  3. スキル  4. 逃げる    |\n");
    printf("  +---------------------------+\n");
    printf("  &gt; ");
}

// === 戦闘 ===
int calc_damage(int attack, int defense, int *is_crit) {
    *is_crit = 0;

    int base = attack - defense;
    if (base &lt; 1) base = 1;

    int range = base / 4;
    if (range &lt; 1) range = 1;
    int variation = rand() % (range * 2 + 1) - range;
    int damage = base + variation;

    if (rand() % 100 &lt; 15) {
        *is_crit = 1;
        damage = (int)(damage * 1.5);
    }

    if (damage &lt; 1) damage = 1;
    return damage;
}

void do_player_attack(void) {
    int is_crit;
    int damage = calc_damage(player_attack, enemy_defense, &amp;is_crit);

    printf("\n  勇者の攻撃！");
    if (is_crit) printf(" ★★★ 会心の一撃！ ★★★");
    printf("\n  %dダメージ！\n", damage);

    enemy_hp -= damage;
    if (enemy_hp &lt; 0) enemy_hp = 0;
}

void do_player_defend(int *defending) {
    printf("\n  勇者は身を守っている！\n");
    printf("  （このターン、受けるダメージが半減）\n");
    *defending = 1;
}

void do_player_skill(void) {
    if (player_mp &lt; 10) {
        printf("\n  MPが足りません！\n");
        return;
    }

    player_mp -= 10;

    int skill_attack = (int)(player_attack * 1.5);
    int is_crit;
    int damage = calc_damage(skill_attack, enemy_defense, &amp;is_crit);

    printf("\n  勇者のパワースラッシュ！（MP -10）\n");
    if (is_crit) printf("  ★★★ 会心の一撃！ ★★★\n");
    printf("  %dダメージ！\n", damage);

    enemy_hp -= damage;
    if (enemy_hp &lt; 0) enemy_hp = 0;
}

int try_escape(void) {
    printf("\n  勇者は逃げ出そうとした...\n");

    if (rand() % 100 &lt; 40) {
        printf("  うまく逃げ切れた！\n");
        return 1;
    } else {
        printf("  しかし回り込まれてしまった！\n");
        return 0;
    }
}

void do_enemy_turn(int defending) {
    int is_crit;
    int effective_defense = defending ? player_defense * 2 : player_defense;
    int damage = calc_damage(enemy_attack, effective_defense, &amp;is_crit);

    printf("\n  %sの攻撃！", enemy_names[enemy_type]);
    if (defending) printf(" ガード！");
    printf("\n  %dダメージ！\n", damage);

    player_hp -= damage;
    if (player_hp &lt; 0) player_hp = 0;
}

void check_level_up(void) {
    int required = player_level * 100;

    if (player_exp &gt;= required) {
        player_level++;
        player_exp -= required;

        player_max_hp += 15;
        player_max_mp += 5;
        player_attack += 3;
        player_defense += 2;

        player_hp = player_max_hp;
        player_mp = player_max_mp;

        printf("\n  ** レベルアップ！ **\n");
        printf("  レベル%dになった！\n", player_level);
        printf("  HP: %d  MP: %d  攻撃力: %d  防御力: %d\n",
               player_max_hp, player_max_mp, player_attack, player_defense);
    }
}

// === メイン ===
int main(void) {
    srand(time(NULL));

    init_player();
    show_title();
    getchar();

    int battle_count = 0;
    int game_over = 0;

    while (!game_over) {
        battle_count++;
        printf("\n===== 戦闘%d =====\n", battle_count);

        init_enemy();
        printf("  %sが現れた！\n", enemy_names[enemy_type]);

        int battle_end = 0;

        while (!battle_end) {
            show_status();
            show_menu();

            int cmd;
            scanf("%d", &amp;cmd);

            int is_defending = 0;
            int skip_enemy = 0;

            switch (cmd) {
                case 1:
                    do_player_attack();
                    break;
                case 2:
                    do_player_defend(&amp;is_defending);
                    break;
                case 3:
                    do_player_skill();
                    break;
                case 4:
                    if (try_escape()) {
                        battle_end = 1;
                        skip_enemy = 1;
                    }
                    break;
                default:
                    printf("  無効なコマンドです！\n");
                    continue;
            }

            if (skip_enemy) continue;

            if (enemy_hp &lt;= 0) {
                printf("\n+========================================+\n");
                printf("|         *** 勝利！ ***                 |\n");
                printf("+========================================+\n");

                player_exp += enemy_exp_reward;
                printf("  %dの経験値を獲得！\n", enemy_exp_reward);

                check_level_up();
                battle_end = 1;
                continue;
            }

            do_enemy_turn(is_defending);

            if (player_hp &lt;= 0) {
                printf("\n+========================================+\n");
                printf("|       *** ゲームオーバー ***           |\n");
                printf("+========================================+\n");
                game_over = 1;
                battle_end = 1;
            }
        }

        if (!game_over) {
            printf("\n  続けますか？（1=はい / 0=いいえ）: ");
            int choice;
            scanf("%d", &amp;choice);
            if (choice != 1) {
                game_over = 1;
            }
        }
    }

    printf("\n+========================================+\n");
    printf("|        お疲れさまでした！              |\n");
    printf("|   戦闘回数: %d\n", battle_count);
    printf("|   最終レベル: %d\n", player_level);
    printf("+========================================+\n");

    return 0;
}
</code></pre>

