int calc_damage(int kougeki, int bougyo, int *is_critical) {
    *is_critical = 0;

    int base = kougeki - bougyo;
    if (base &lt; 1) base = 1;

    // ±20%のばらつき
    int hani = base / 5;
    if (hani &lt; 1) hani = 1;
    int damage = base + (rand() % (hani * 2 + 1) - hani);

    // 15%で会心
    if (rand() % 100 &lt; 15) {
        *is_critical = 1;
        damage = (int)(damage * 1.5);
    }

    if (damage &lt; 1) damage = 1;
    return damage;
}

void apply_damage(int *hp, int damage) {
    *hp -= damage;
    if (*hp &lt; 0) *hp = 0;
}

void do_kougeki(const char *name, int atk, int def, 
                int *target_hp, int *is_critical) {
    int damage = calc_damage(atk, def, is_critical);
    int old_hp = *target_hp;
    apply_damage(target_hp, damage);

    printf("%sの攻撃！\n", name);
    printf("ダメージ: %d, 会心: %s\n", 
           damage, *is_critical ? "あり" : "なし");
    printf("HP: %d -&gt; %d\n\n", old_hp, *target_hp);
}

