    // 範囲チェック
    if (new_y &lt; 0 || new_y &gt;= TATE || new_x &lt; 0 || new_x &gt;= YOKO) {
        printf("マップの外には出られません！\n");
        return 0;
    }

    // 壁チェック
    if (maps[player_floor][new_y][new_x] == 1) {
        printf("壁があって進めません！\n");
        return 0;
    }

    player_y = new_y;
    player_x = new_x;
    return 1;
}

// === 敵チェック ===
Teki* check_teki(void) {
    for (int i = 0; i &lt; teki_count; i++) {
        if (tekis[i].alive &amp;&amp; 
            tekis[i].floor == player_floor &amp;&amp;
            tekis[i].y == player_y &amp;&amp; 
            tekis[i].x == player_x) {
            return &amp;tekis[i];
        }
    }
    return NULL;
}

// === ダメージ計算 ===
int calc_damage(int atk, int def, int *is_crit) {
    *is_crit = 0;
    int base = atk - def;
    if (base &lt; 1) base = 1;

    int hani = base / 4;
    if (hani &lt; 1) hani = 1;
    int damage = base + (rand() % (hani * 2 + 1) - hani);

    if (rand() % 100 &lt; 15) {
        *is_crit = 1;
        damage = (int)(damage * 1.5);
    }

    if (damage &lt; 1) damage = 1;
    return damage;
}

// === 戦闘 ===
void sentou(Teki *teki) {
    printf("\n=== 戦闘開始 ===\n");
    printf("%sが現れた！\n", teki-&gt;namae);

    while (player_hp &gt; 0 &amp;&amp; teki-&gt;hp &gt; 0) {
        printf("\n%s HP: %d/%d\n", teki-&gt;namae, teki-&gt;hp, teki-&gt;max_hp);
        printf("勇者 HP: %d/%d  MP: %d/%d\n", 
               player_hp, player_max_hp, player_mp, player_max_mp);

        printf("\n+---------------------------+\n");
        printf("|  1. 攻撃    2. 防御      |\n");
        printf("|  3. スキル  4. 逃げる    |\n");
        printf("+---------------------------+\n");
        printf("&gt; ");

        int cmd;
        scanf("%d", &amp;cmd);

        int is_bougyo = 0;
        int escaped = 0;

        switch (cmd) {
            case 1: {
                int is_crit;
                int damage = calc_damage(player_atk, teki-&gt;def, &amp;is_crit);
                printf("\n勇者の攻撃！");
                if (is_crit) printf(" ★会心の一撃！");
                printf("\n%dダメージ！\n", damage);
                teki-&gt;hp -= damage;
                break;
            }
            case 2:
                printf("\n勇者は身を守っている！\n");
                is_bougyo = 1;
                break;
            case 3:
                if (player_mp &lt; 10) {
                    printf("\nMPが足りません！\n");
                    continue;
                }
                player_mp -= 10;
                int is_crit;
                int damage = calc_damage((int)(player_atk * 1.5), teki-&gt;def, &amp;is_crit);
                printf("\n勇者のパワースラッシュ！ (MP -10)\n");
                if (is_crit) printf("★会心の一撃！\n");
                printf("%dダメージ！\n", damage);
                teki-&gt;hp -= damage;
                break;
            case 4:
                if (rand() % 100 &lt; 40) {
                    printf("\nうまく逃げ切った！\n");
                    escaped = 1;
                } else {
                    printf("\n逃げられなかった！\n");
                }
                break;
            default:
                printf("\n無効なコマンドです\n");
                continue;
        }

        if (escaped) {
            player_y = 1;
            player_x = 1;
            return;
        }

        if (teki-&gt;hp &lt;= 0) break;

        // 敵の攻撃
        int is_crit;
        int def = is_bougyo ? player_def * 2 : player_def;
        int damage = calc_damage(teki-&gt;atk, def, &amp;is_crit);
        printf("\n%sの攻撃！ %dダメージ！\n", teki-&gt;namae, damage);
        player_hp -= damage;
    }

    if (player_hp &gt; 0) {
        printf("\n=== 勝利！ ===\n");
        printf("%dの経験値を獲得！\n", teki-&gt;exp);
        player_exp += teki-&gt;exp;
        teki-&gt;alive = 0;
        check_levelup();
    } else {
        printf("\n=== ゲームオーバー ===\n");
        exit(0);
    }
}

// === レベルアップ ===
void check_levelup(void) {
    int required = player_level * 100;
    if (player_exp &gt;= required) {
        player_level++;
        player_exp -= required;
        player_max_hp += 15;
        player_max_mp += 5;
        player_atk += 3;
        player_def += 2;
        player_hp = player_max_hp;
        player_mp = player_max_mp;

        printf("\n★★★ レベルアップ！ ★★★\n");
        printf("レベル%dになった！\n", player_level);
    }
}

// === メイン ===
int main(void) {
    srand(time(NULL));

    printf("+========================================+\n");
    printf("|       ダンジョン探索 RPG - Week 2      |\n");
    printf("+========================================+\n");

    while (1) {
        show_map();
        show_status();

        printf("\n移動 (w/a/s/d, q=終了): ");
        char key;
        scanf(" %c", &amp;key);

        if (key == 'q') {
            printf("ゲームを終了します。\n");
            break;
        }

        if (!idou(key)) continue;

        // 敵チェック
        Teki *teki = check_teki();
        if (teki != NULL) {
            sentou(teki);
            if (player_hp &lt;= 0) break;
        }

        // 階段チェック
        if (maps[player_floor][player_y][player_x] == 4) {
            printf("\n階段を発見！次の階へ進みますか？(y/n): ");
            char choice;
            scanf(" %c", &amp;choice);

            if (choice == 'y') {
                player_floor++;
                if (player_floor &gt;= MAX_FLOOR) {
                    printf("\n+========================================+\n");
                    printf("|      ダンジョンクリア！おめでとう！     |\n");
                    printf("+========================================+\n");
                    break;
                }
