Member* create_member(const char *name, int hp) {
    Member *m = (Member*)malloc(sizeof(Member));
    if (m == NULL) return NULL;

    m-&gt;name = (char*)malloc(strlen(name) + 1);
    if (m-&gt;name == NULL) {
        free(m);
        return NULL;
    }

    strcpy(m-&gt;name, name);
    m-&gt;hp = hp;
    return m;
}

void free_member(Member *m) {
    if (m == NULL) return;
    free(m-&gt;name);
    free(m);
}

Party* create_party(int initial_capacity) {
    Party *p = (Party*)malloc(sizeof(Party));
    if (p == NULL) return NULL;

    p-&gt;members = (Member**)calloc(initial_capacity, sizeof(Member*));
    if (p-&gt;members == NULL) {
        free(p);
        return NULL;
    }

    p-&gt;count = 0;
    p-&gt;capacity = initial_capacity;
    return p;
}

void free_party(Party *p) {
    if (p == NULL) return;

    // 全メンバーを解放
    for (int i = 0; i &lt; p-&gt;count; i++) {
        free_member(p-&gt;members[i]);
    }

    free(p-&gt;members);
    free(p);
    printf("[DEBUG] パーティメモリ解放完了\n");
}

int add_member(Party *p, const char *name, int hp) {
    if (p == NULL) return 0;

    // 容量拡張
    if (p-&gt;count &gt;= p-&gt;capacity) {
        int new_cap = p-&gt;capacity * 2;
        Member **temp = (Member**)realloc(p-&gt;members, 
                                          new_cap * sizeof(Member*));
        if (temp == NULL) return 0;
        p-&gt;members = temp;
        p-&gt;capacity = new_cap;
    }

    Member *m = create_member(name, hp);
    if (m == NULL) return 0;

    p-&gt;members[p-&gt;count] = m;
    p-&gt;count++;
    return 1;
}

void show_party(Party *p) {
    if (p == NULL) return;

    printf("=== パーティ (%d/%d) ===\n", p-&gt;count, p-&gt;capacity);
    for (int i = 0; i &lt; p-&gt;count; i++) {
        printf("[%d] %s HP:%d\n", 
               i, p-&gt;members[i]-&gt;name, p-&gt;members[i]-&gt;hp);
    }
}

