dungeon_v4.c の正解（長いので一部抜粋） <pre><code>/*
 * ダンジョン探索 RPG - アイテムシステム (Week 4)
 * 完全版は約500行
 */

#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;time.h&gt;
#include &lt;string.h&gt;

// === 型定義 ===
typedef enum { ITEM_HEAL, ITEM_HEAL_MP, ITEM_WEAPON, ITEM_ARMOR } ItemType;

typedef struct {
    int id;
    char name[20];
    char desc[30];
    ItemType type;
    int value;
    int price;
} Item;

typedef struct { int item_id; int count; } InvSlot;

typedef struct {
    InvSlot *slots;
    int size;
    int gold;
} Inventory;

typedef struct {
    char name[20];
    int hp, max_hp;
    int mp, max_mp;
    int atk, def;
    int level, exp;
    int weapon_id, armor_id;
} Player;

typedef struct {
    int item_id;
    int rate;
} DropEntry;

typedef struct {
    char name[20];
    int hp, max_hp;
    int atk, def;
    int exp;
    DropEntry drops[3];
    int drop_count;
} Teki;

// === グローバル ===
Item item_master[] = {
    {0, "", "", 0, 0, 0},
    {1, "薬草", "HP+30", ITEM_HEAL, 30, 10},
    {2, "上薬草", "HP+80", ITEM_HEAL, 80, 30},
    {3, "魔法の水", "MP+20", ITEM_HEAL_MP, 20, 25},
    {4, "銅の剣", "ATK+5", ITEM_WEAPON, 5, 100},
    {5, "鉄の剣", "ATK+12", ITEM_WEAPON, 12, 300},
    {6, "皮の盾", "DEF+3", ITEM_ARMOR, 3, 80}
};
#define ITEM_COUNT 7

Item* get_item(int id) {
    if (id &lt; 0 || id &gt;= ITEM_COUNT) return &amp;item_master[0];
    return &amp;item_master[id];
}

// === インベントリ ===
Inventory* create_inventory(int size) {
    Inventory *inv = (Inventory*)malloc(sizeof(Inventory));
    if (!inv) return NULL;
    inv-&gt;slots = (InvSlot*)calloc(size, sizeof(InvSlot));
    if (!inv-&gt;slots) { free(inv); return NULL; }
    inv-&gt;size = size;
    inv-&gt;gold = 100;
    return inv;
}

void free_inventory(Inventory *inv) {
    if (!inv) return;
    free(inv-&gt;slots);
    free(inv);
}

int add_item(Inventory *inv, int item_id, int count) {
    for (int i = 0; i &lt; inv-&gt;size; i++) {
        if (inv-&gt;slots[i].item_id == item_id) {
            inv-&gt;slots[i].count += count;
            return 1;
        }
    }
    for (int i = 0; i &lt; inv-&gt;size; i++) {
        if (inv-&gt;slots[i].item_id == 0) {
            inv-&gt;slots[i].item_id = item_id;
            inv-&gt;slots[i].count = count;
            return 1;
        }
    }
    return 0;
}

int remove_item(Inventory *inv, int item_id, int count) {
    for (int i = 0; i &lt; inv-&gt;size; i++) {
        if (inv-&gt;slots[i].item_id == item_id) {
            if (inv-&gt;slots[i].count &lt; count) return 0;
            inv-&gt;slots[i].count -= count;
            if (inv-&gt;slots[i].count == 0) inv-&gt;slots[i].item_id = 0;
            return 1;
        }
    }
    return 0;
}

// === プレイヤー ===
Player* create_player(const char *name) {
    Player *p = (Player*)malloc(sizeof(Player));
    if (!p) return NULL;
    strcpy(p-&gt;name, name);
    p-&gt;hp = p-&gt;max_hp = 100;
    p-&gt;mp = p-&gt;max_mp = 30;
    p-&gt;atk = 15;
    p-&gt;def = 8;
    p-&gt;level = 1;
    p-&gt;exp = 0;
    p-&gt;weapon_id = 0;
    p-&gt;armor_id = 0;
    return p;
}

void free_player(Player *p) {
    free(p);
}

int get_player_atk(Player *p) {
    int bonus = 0;
    if (p-&gt;weapon_id &gt; 0) {
        bonus = get_item(p-&gt;weapon_id)-&gt;value;
    }
    return p-&gt;atk + bonus;
}

int get_player_def(Player *p) {
    int bonus = 0;
    if (p-&gt;armor_id &gt; 0) {
        bonus = get_item(p-&gt;armor_id)-&gt;value;
    }
    return p-&gt;def + bonus;
}

// === 戦闘中アイテム使用 ===
int use_battle_item(Player *p, Inventory *inv) {
    printf("\n=== アイテム ===\n");
    int found = 0;
    for (int i = 0; i &lt; inv-&gt;size; i++) {
        if (inv-&gt;slots[i].item_id &gt; 0) {
            Item *item = get_item(inv-&gt;slots[i].item_id);
            if (item-&gt;type == ITEM_HEAL || item-&gt;type == ITEM_HEAL_MP) {
                printf("[%d] %-10s x%d  %s\n", i, item-&gt;name, 
                       inv-&gt;slots[i].count, item-&gt;desc);
                found = 1;
            }
        }
    }
    if (!found) {
        printf("使えるアイテムがありません\n");
        return 0;
    }

    printf("戻る: 9\n&gt; ");
    int slot;
    scanf("%d", &amp;slot);

    if (slot == 9) return 0;
    if (slot &lt; 0 || slot &gt;= inv-&gt;size) return 0;
    if (inv-&gt;slots[slot].item_id == 0) return 0;

    Item *item = get_item(inv-&gt;slots[slot].item_id);

    if (item-&gt;type == ITEM_HEAL) {
        int old = p-&gt;hp;
        p-&gt;hp += item-&gt;value;
        if (p-&gt;hp &gt; p-&gt;max_hp) p-&gt;hp = p-&gt;max_hp;
        printf("\n%sを使用！\n", item-&gt;name);
        printf("HP: %d -&gt; %d\n", old, p-&gt;hp);
    } else if (item-&gt;type == ITEM_HEAL_MP) {
        int old = p-&gt;mp;
        p-&gt;mp += item-&gt;value;
        if (p-&gt;mp &gt; p-&gt;max_mp) p-&gt;mp = p-&gt;max_mp;
        printf("\n%sを使用！\n", item-&gt;name);
        printf("MP: %d -&gt; %d\n", old, p-&gt;mp);
    }

    remove_item(inv, inv-&gt;slots[slot].item_id, 1);
    return 1;
}

// === ドロップ判定 ===
void check_drops(Teki *teki, Inventory *inv) {
    for (int i = 0; i &lt; teki-&gt;drop_count; i++) {
        if (rand() % 100 &lt; teki-&gt;drops[i].rate) {
            Item *item = get_item(teki-&gt;drops[i].item_id);
            printf("%sは「%s」を落とした！\n", teki-&gt;name, item-&gt;name);
            add_item(inv, teki-&gt;drops[i].item_id, 1);
        }
    }
}

