dungeon_v5.c の正解（長いので構造のみ） <pre><code>/*
 * ダンジョン探索 RPG - セーブシステム (Week 5)
 * 完全版は約600行
 */

#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;string.h&gt;
#include &lt;time.h&gt;
#include &lt;stdarg.h&gt;

// === 定数 ===
#define SAVE_MAGIC "DUNG"
#define SAVE_VERSION 1
#define MAX_SLOTS 3
#define MAP_WIDTH 10
#define MAP_HEIGHT 7

// === ログシステム ===
typedef enum { LOG_DEBUG, LOG_INFO, LOG_WARN, LOG_ERROR } LogLevel;

void log_msg(LogLevel level, const char *fmt, ...) {
    // 実装省略（5.9参照）
}

#define LOG_I(fmt, ...) log_msg(LOG_INFO, fmt, ##__VA_ARGS__)
#define LOG_E(fmt, ...) log_msg(LOG_ERROR, fmt, ##__VA_ARGS__)

// === データ構造 ===
typedef struct {
    char name[20];
    int hp, max_hp, mp, max_mp;
    int atk, def, level, exp;
    int floor, pos_x, pos_y;
} PlayerData;

typedef struct {
    int items[20], counts[20];
    int gold;
} InventoryData;

typedef struct {
    char magic[4];
    int version;
    time_t save_time;
    PlayerData player;
    InventoryData inventory;
} SaveFile;

// === グローバル変数 ===
PlayerData g_player;
InventoryData g_inventory;
char g_map[MAP_HEIGHT][MAP_WIDTH + 1];
int g_running = 1;

// === セーブ/ロード ===
int save_to_slot(int slot) {
    char filename[20];
    sprintf(filename, "save%d.dat", slot);

    SaveFile save = {0};
    memcpy(save.magic, SAVE_MAGIC, 4);
    save.version = SAVE_VERSION;
    save.save_time = time(NULL);
    save.player = g_player;
    save.inventory = g_inventory;

    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        LOG_E("セーブ失敗: %s", filename);
        return 0;
    }

    fwrite(&amp;save, sizeof(SaveFile), 1, fp);
    fclose(fp);

    LOG_I("セーブ完了: slot %d", slot);
    return 1;
}

int load_from_slot(int slot) {
    char filename[20];
    sprintf(filename, "save%d.dat", slot);

    FILE *fp = fopen(filename, "rb");
    if (!fp) {
        LOG_E("ロード失敗: %s", filename);
        return 0;
    }

    SaveFile save;
    fread(&amp;save, sizeof(SaveFile), 1, fp);
    fclose(fp);

    if (memcmp(save.magic, SAVE_MAGIC, 4) != 0) {
        LOG_E("無効なセーブファイル");
        return 0;
    }

    g_player = save.player;
    g_inventory = save.inventory;

    LOG_I("ロード完了: slot %d", slot);
    return 1;
}

// === スロット表示 ===
void show_slots(void) {
    printf("\n=== セーブスロット ===\n");

    for (int i = 1; i &lt;= MAX_SLOTS; i++) {
        char filename[20];
        sprintf(filename, "save%d.dat", i);

        FILE *fp = fopen(filename, "rb");
        printf("[%d] ", i);

        if (fp) {
            SaveFile save;
            fread(&amp;save, sizeof(SaveFile), 1, fp);
            fclose(fp);

            char time_str[20];
            struct tm *tm = localtime(&amp;save.save_time);
            strftime(time_str, 20, "%m/%d %H:%M", tm);

            printf("%-10s Lv.%-3d %d階  %s\n",
                   save.player.name, save.player.level,
                   save.player.floor, time_str);
        } else {
            printf("--- 空き ---\n");
        }
    }
}

// === ゲームループ ===
void game_loop(void) {
    while (g_running) {
        // マップ表示
        show_map();

        // 入力処理
        printf("wasd:移動 i:アイテム m:メニュー q:タイトル\n&gt; ");
        char cmd;
        scanf(" %c", &amp;cmd);

        switch (cmd) {
            case 'w': case 'a': case 's': case 'd':
                move_player(cmd);
                break;
            case 'i':
                item_menu();
                break;
            case 'm':
                game_menu();
                break;
            case 'q':
                return;
        }
    }
}

// === メイン ===
int main(void) {
    srand(time(NULL));

    // ログ初期化
    FILE *fp = fopen("game.log", "w");
    if (fp) { fprintf(fp, "=== ゲームログ ===\n"); fclose(fp); }

    LOG_I("ゲーム開始");

    // タイトル画面
    while (1) {
        printf("\n+========================================+\n");
        printf("|       ダンジョン探索 RPG - Week 5      |\n");
        printf("+========================================+\n\n");

        printf("1. はじめから\n");
        printf("2. つづきから\n");
        printf("0. 終了\n");
        printf("&gt; ");

        int cmd;
        scanf("%d", &amp;cmd);

        if (cmd == 0) break;

        if (cmd == 1) {
            // 新規ゲーム
            strcpy(g_player.name, "勇者");
            g_player.hp = g_player.max_hp = 100;
            g_player.mp = g_player.max_mp = 30;
            g_player.atk = 15;
            g_player.def = 8;
            g_player.level = 1;
            g_player.floor = 1;
            g_player.pos_x = 1;
            g_player.pos_y = 1;
            g_inventory.gold = 100;

            game_loop();
        }

        if (cmd == 2) {
            show_slots();
            printf("ロードするスロット (1-%d, 0=戻る): ", MAX_SLOTS);
            int slot;
            scanf("%d", &amp;slot);

            if (slot &gt;= 1 &amp;&amp; slot &lt;= MAX_SLOTS) {
                if (load_from_slot(slot)) {
                    printf("ロード完了！\n");
                    game_loop();
                }
            }
        }
    }

    LOG_I("ゲーム終了");

    return 0;
}
