#include "score.h"

// 公開変数
int g_current_score = 0;
int g_high_score = 0;

// 非公開変数
static int s_history[10] = {0};
static int s_history_count = 0;

// 非公開関数
static int validate_points(int points) {
    if (points &lt; 0) return 0;
    if (points &gt; 10000) return 10000;
    return points;
}

static void add_to_history(int score) {
    if (s_history_count &lt; 10) {
        s_history[s_history_count] = score;
        s_history_count++;
    }
}

// 公開関数
void score_init(void) {
    g_current_score = 0;
    s_history_count = 0;
}

void score_add(int points) {
    points = validate_points(points);
    g_current_score += points;
    printf("+%d points! (Total: %d)\n", points, g_current_score);
}

void score_reset(void) {
    add_to_history(g_current_score);
    g_current_score = 0;
}

int score_check_highscore(void) {
    if (g_current_score &gt; g_high_score) {
        g_high_score = g_current_score;
        printf("★ NEW HIGH SCORE: %d ★\n", g_high_score);
        return 1;
    }
    return 0;
}

