アサーション追加版（自分で試してから見てください） <pre><code>#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;string.h&gt;
#include &lt;assert.h&gt;

#define MAX_INVENTORY 10

typedef struct {
    char name[20];
    int hp, max_hp;
    int atk, def;
    int level;
} Player;

typedef struct {
    int item_ids[MAX_INVENTORY];
    int count;
} Inventory;

Player* create_player(const char *name) {
    assert(name != NULL);

    Player *p = malloc(sizeof(Player));
    assert(p != NULL);  // メモリ確保成功

    strncpy(p-&gt;name, name, 19);
    p-&gt;name[19] = '\0';
    p-&gt;hp = p-&gt;max_hp = 100;
    p-&gt;atk = 20;
    p-&gt;def = 10;
    p-&gt;level = 1;

    // 不変条件
    assert(p-&gt;hp &gt; 0);
    assert(p-&gt;hp &lt;= p-&gt;max_hp);
    assert(p-&gt;level &gt;= 1);

    return p;
}

void damage_player(Player *p, int amount) {
    // 前提条件
    assert(p != NULL);
    assert(amount &gt;= 0);

    int old_hp = p-&gt;hp;
    p-&gt;hp -= amount;
    if (p-&gt;hp &lt; 0) p-&gt;hp = 0;

    // 不変条件
    assert(p-&gt;hp &gt;= 0);
    assert(p-&gt;hp &lt;= p-&gt;max_hp);
    assert(p-&gt;hp &lt;= old_hp);  // HPは減るか変わらない
}

void heal_player(Player *p, int amount) {
    // 前提条件
    assert(p != NULL);
    assert(amount &gt;= 0);

    int old_hp = p-&gt;hp;
    p-&gt;hp += amount;
    if (p-&gt;hp &gt; p-&gt;max_hp) p-&gt;hp = p-&gt;max_hp;

    // 不変条件
    assert(p-&gt;hp &gt;= 0);
    assert(p-&gt;hp &lt;= p-&gt;max_hp);
    assert(p-&gt;hp &gt;= old_hp);  // HPは増えるか変わらない
}

void level_up(Player *p) {
    // 前提条件
    assert(p != NULL);
    assert(p-&gt;level &gt;= 1);

    int old_level = p-&gt;level;
    int old_max_hp = p-&gt;max_hp;

    p-&gt;level++;
    p-&gt;max_hp += 10;
    p-&gt;atk += 3;
    p-&gt;def += 2;
    p-&gt;hp = p-&gt;max_hp;

    // 不変条件
    assert(p-&gt;level == old_level + 1);
    assert(p-&gt;max_hp &gt; old_max_hp);
    assert(p-&gt;hp == p-&gt;max_hp);
}

int add_item(Inventory *inv, int item_id) {
    // 前提条件
    assert(inv != NULL);
    assert(inv-&gt;count &gt;= 0);
    assert(inv-&gt;count &lt; MAX_INVENTORY);  // 空きがある
    assert(item_id &gt; 0);  // 有効なアイテムID

    int old_count = inv-&gt;count;

    inv-&gt;item_ids[inv-&gt;count] = item_id;
    inv-&gt;count++;

    // 不変条件
    assert(inv-&gt;count == old_count + 1);
    assert(inv-&gt;count &lt;= MAX_INVENTORY);

    return 1;
}

int remove_item(Inventory *inv, int index) {
    // 前提条件
    assert(inv != NULL);
    assert(inv-&gt;count &gt; 0);  // アイテムがある
    assert(index &gt;= 0);
    assert(index &lt; inv-&gt;count);  // 有効なインデックス

    int old_count = inv-&gt;count;

    for (int i = index; i &lt; inv-&gt;count - 1; i++) {
        inv-&gt;item_ids[i] = inv-&gt;item_ids[i + 1];
    }
    inv-&gt;count--;

    // 不変条件
    assert(inv-&gt;count == old_count - 1);
    assert(inv-&gt;count &gt;= 0);

    return 1;
}

int main(void) {
    Player *hero = create_player("勇者");

    damage_player(hero, 30);
    printf("HP: %d/%d\n", hero-&gt;hp, hero-&gt;max_hp);

    heal_player(hero, 20);
    printf("HP: %d/%d\n", hero-&gt;hp, hero-&gt;max_hp);

    level_up(hero);
    printf("Lv.%d HP: %d/%d\n", hero-&gt;level, hero-&gt;hp, hero-&gt;max_hp);

    Inventory inv = {{0}, 0};
    add_item(&amp;inv, 1);
    add_item(&amp;inv, 2);
    add_item(&amp;inv, 3);
    printf("アイテム数: %d\n", inv.count);

    remove_item(&amp;inv, 1);
    printf("アイテム数: %d\n", inv.count);

    free(hero);
    return 0;
}
