}

int inventory_remove(Inventory *inv, int index) {
    if (inv == NULL) return 0;
    if (index &lt; 0 || index &gt;= inv-&gt;count) return 0;

    for (int i = index; i &lt; inv-&gt;count - 1; i++) {
        inv-&gt;items[i] = inv-&gt;items[i + 1];
    }
    inv-&gt;items[inv-&gt;count - 1] = 0;
    inv-&gt;count--;
