エラー処理追加版（自分で試してから見てください） <pre><code>#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;

#define MAX_ITEMS 10

// エラーコード
typedef enum {
    INV_OK = 0,
    INV_ERR_NULL,
    INV_ERR_FULL,
    INV_ERR_EMPTY,
    INV_ERR_INVALID_INDEX,
    INV_ERR_INVALID_ITEM
} InvResult;

const char* inv_error_str(InvResult r) {
    switch (r) {
        case INV_OK:              return "成功";
        case INV_ERR_NULL:        return "NULLポインタ";
        case INV_ERR_FULL:        return "インベントリが満杯";
        case INV_ERR_EMPTY:       return "インベントリが空";
        case INV_ERR_INVALID_INDEX: return "無効なインデックス";
        case INV_ERR_INVALID_ITEM:  return "無効なアイテムID";
        default:                  return "不明なエラー";
    }
}

typedef struct {
    int items[MAX_ITEMS];
    int count;
} Inventory;

void inventory_init(Inventory *inv) {
    if (inv == NULL) return;

    for (int i = 0; i &lt; MAX_ITEMS; i++) {
        inv-&gt;items[i] = 0;
    }
    inv-&gt;count = 0;
}

InvResult add_item(Inventory *inv, int item_id) {
    // 引数チェック
    if (inv == NULL) {
        return INV_ERR_NULL;
    }
    if (item_id &lt;= 0) {
        return INV_ERR_INVALID_ITEM;
    }
    if (inv-&gt;count &gt;= MAX_ITEMS) {
        return INV_ERR_FULL;
    }

    // 追加
    inv-&gt;items[inv-&gt;count] = item_id;
    inv-&gt;count++;

    return INV_OK;
}

InvResult remove_item(Inventory *inv, int index) {
    // 引数チェック
    if (inv == NULL) {
        return INV_ERR_NULL;
    }
    if (inv-&gt;count == 0) {
        return INV_ERR_EMPTY;
    }
    if (index &lt; 0 || index &gt;= inv-&gt;count) {
        return INV_ERR_INVALID_INDEX;
    }

    // 削除（詰める）
    for (int i = index; i &lt; inv-&gt;count - 1; i++) {
        inv-&gt;items[i] = inv-&gt;items[i + 1];
    }
    inv-&gt;items[inv-&gt;count - 1] = 0;
    inv-&gt;count--;

    return INV_OK;
}

InvResult get_item(Inventory *inv, int index, int *out_item_id) {
    // 引数チェック
    if (inv == NULL || out_item_id == NULL) {
        return INV_ERR_NULL;
    }
    if (inv-&gt;count == 0) {
        return INV_ERR_EMPTY;
    }
    if (index &lt; 0 || index &gt;= inv-&gt;count) {
        return INV_ERR_INVALID_INDEX;
    }

    *out_item_id = inv-&gt;items[index];
    return INV_OK;
}

int main(void) {
