    printf("NULL追加: %s\n", inv_error_str(result));

    result = add_item(&amp;inv, -1);
    printf("無効ID追加: %s\n", inv_error_str(result));

    result = remove_item(&amp;inv, 10);
    printf("範囲外削除: %s\n", inv_error_str(result));

    // 満杯テスト
    for (int i = 0; i &lt; 20; i++) {
        result = add_item(&amp;inv, i + 10);
        if (result != INV_OK) {
            printf("追加[%d]: %s\n", i, inv_error_str(result));
            break;
        }
    }

    return 0;
}
