問題点と修正（自分で考えてから見てください）  ### 発見された問題  1. **create関数**:    - `malloc`の戻り値チェックなし    - `strlen(n)` は`+1`が必要（null終端分）    - 引数`n`のNULLチェックなし    - `item_count`が初期化されていない  2. **add_item関数**:    - NULLチェックなし    - 配列の境界チェックなし（10個まで）  3. **get_item関数**:    - NULLチェックなし    - インデックスの境界チェックなし  4. **destroy関数**:    - `p-&gt;name`を解放していない（メモリリーク）    - NULLチェックなし  5. **main関数**:    - 15個のアイテムを追加（配列オーバーフロー）    - インデックス12にアクセス（範囲外）    - 解放後にhero-&gt;nameにアクセス（use after free）  ### 修正後のコード  <pre><code>#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;string.h&gt;

#define MAX_ITEMS 10

typedef struct {
    char *name;
    int hp;
    int items[MAX_ITEMS];
    int item_count;
} Player;

Player* create(const char *name) {
    if (name == NULL) return NULL;

    Player *p = malloc(sizeof(Player));
    if (p == NULL) return NULL;

    p-&gt;name = malloc(strlen(name) + 1);  // +1 追加
    if (p-&gt;name == NULL) {
        free(p);
        return NULL;
    }

    strcpy(p-&gt;name, name);
    p-&gt;hp = 100;
    p-&gt;item_count = 0;  // 初期化追加

    for (int i = 0; i &lt; MAX_ITEMS; i++) {
        p-&gt;items[i] = 0;
    }

    return p;
}

int add_item(Player *p, int id) {
    if (p == NULL) return 0;
    if (p-&gt;item_count &gt;= MAX_ITEMS) return 0;  // 境界チェック

    p-&gt;items[p-&gt;item_count] = id;
    p-&gt;item_count++;
    return 1;
}

int get_item(Player *p, int index, int *out_id) {
    if (p == NULL || out_id == NULL) return 0;
    if (index &lt; 0 || index &gt;= p-&gt;item_count) return 0;  // 境界チェック

    *out_id = p-&gt;items[index];
    return 1;
}

void destroy(Player *p) {
    if (p == NULL) return;

    free(p-&gt;name);  // nameも解放
    p-&gt;name = NULL;
    free(p);
}

int main(void) {
    Player *hero = create("勇者");
    if (hero == NULL) {
        printf("作成失敗\n");
        return 1;
    }

    // 10個まで追加
    for (int i = 0; i &lt; 15; i++) {
        if (!add_item(hero, i)) {
            printf("アイテム追加失敗: %d\n", i);
        }
    }

    int item;
    if (get_item(hero, 5, &amp;item)) {
        printf("Item 5: %d\n", item);
    }

    if (get_item(hero, 12, &amp;item)) {
        printf("Item 12: %d\n", item);
    } else {
        printf("Item 12: 範囲外\n");
    }

    // 解放前にアクセス
    printf("Name: %s\n", hero-&gt;name);

    destroy(hero);
    hero = NULL;  // 解放後はNULL

    return 0;
}
