void add_skill(Player *p, const char *name, int cost, int power);

// プレイヤー作成
Player* create_player(const char *name) {
    if (name == NULL) return NULL;  // 修正: NULLチェック

    Player *p = malloc(sizeof(Player));
    if (p == NULL) return NULL;  // 修正: malloc戻り値チェック

    p-&gt;name = malloc(strlen(name) + 1);  // 修正: +1
    if (p-&gt;name == NULL) {
        free(p);
