    p-&gt;atk = 20;
    p-&gt;def = 10;
    p-&gt;level = 1;
    p-&gt;exp = 0;  // 修正: 経験値初期化
    p-&gt;item_count = 0;  // 修正: 初期化
    p-&gt;skill_count = 0;  // 修正: 初期化

    // スキル追加
    add_skill(p, "斬撃", 0, 0);
    add_skill(p, "ファイア", 10, 30);
    add_skill(p, "ヒール", 15, 40);

    return p;
}

// スキル追加
void add_skill(Player *p, const char *name, int cost, int power) {
    if (p == NULL || name == NULL) return;  // 修正: NULLチェック
    if (p-&gt;skill_count &gt;= MAX_SKILLS) return;  // 修正: 境界チェック

    Skill *s = &amp;p-&gt;skills[p-&gt;skill_count];
    s-&gt;name = malloc(strlen(name) + 1);  // 修正: +1
    if (s-&gt;name == NULL) return;

    strcpy(s-&gt;name, name);
    s-&gt;mp_cost = cost;
    s-&gt;power = power;
    p-&gt;skill_count++;
}

// プレイヤー解放
void free_player(Player *p) {
    if (p == NULL) return;  // 修正: NULLチェック

    // 修正: スキル名の解放
    for (int i = 0; i &lt; p-&gt;skill_count; i++) {
        free(p-&gt;skills[i].name);
    }

    free(p-&gt;name);
    free(p);
}

// 敵作成
Enemy* create_enemy(const char *name, int hp, int atk, int def, int exp) {
    if (name == NULL) return NULL;  // 修正: NULLチェック

    Enemy *e = malloc(sizeof(Enemy));
    if (e == NULL) return NULL;  // 修正: malloc戻り値チェック

    strncpy(e-&gt;name, name, sizeof(e-&gt;name) - 1);  // 修正: strncpy
    e-&gt;name[sizeof(e-&gt;name) - 1] = '\0';
    e-&gt;hp = hp;
    e-&gt;atk = atk;
    e-&gt;def = def;
    e-&gt;exp = exp;
    return e;
}

// ダメージ計算
int calc_damage(int atk, int def) {
    int damage = atk - def;
    if (damage &lt; 1) damage = 1;  // 修正: 最低1ダメージ
    return damage;
}

// 攻撃
void attack(Player *p, Enemy *e) {
    if (p == NULL || e == NULL) return;  // 修正: NULLチェック

    int damage = calc_damage(p-&gt;atk, e-&gt;def);
    e-&gt;hp -= damage;
    if (e-&gt;hp &lt; 0) e-&gt;hp = 0;  // 修正: 下限チェック

    printf("%sの攻撃！ %sに%dダメージ！\n", p-&gt;name, e-&gt;name, damage);
}

// スキル使用
void use_skill(Player *p, Enemy *e, int skill_index) {
    if (p == NULL) return;  // 修正: NULLチェック
    if (skill_index &lt; 0 || skill_index &gt;= p-&gt;skill_count) return;  // 修正: 境界チェック

    Skill *s = &amp;p-&gt;skills[skill_index];

    // 修正: MP足りるかチェック
    if (p-&gt;mp &lt; s-&gt;mp_cost) {
        printf("MPが足りない！\n");
        return;
    }

    p-&gt;mp -= s-&gt;mp_cost;

    if (strcmp(s-&gt;name, "ヒール") == 0) {
        p-&gt;hp += s-&gt;power;
        if (p-&gt;hp &gt; p-&gt;max_hp) p-&gt;hp = p-&gt;max_hp;  // 修正: 上限チェック
        printf("%sはヒールを使った！ HPが%d回復！\n", p-&gt;name, s-&gt;power);
    } else {
        if (e == NULL) return;  // 修正: 攻撃系はeが必要
        int damage = calc_damage(p-&gt;atk + s-&gt;power, e-&gt;def);
        e-&gt;hp -= damage;
        if (e-&gt;hp &lt; 0) e-&gt;hp = 0;
        printf("%sの%s！ %sに%dダメージ！\n", p-&gt;name, s-&gt;name, e-&gt;name, damage);
    }
}

// 敵の攻撃
void enemy_attack(Enemy *e, Player *p) {
    if (e == NULL || p == NULL) return;  // 修正: NULLチェック

    int damage = calc_damage(e-&gt;atk, p-&gt;def);
    p-&gt;hp -= damage;  // 修正: =- を -= に
    if (p-&gt;hp &lt; 0) p-&gt;hp = 0;  // 修正: 下限チェック

    printf("%sの攻撃！ %sに%dダメージ！\n", e-&gt;name, p-&gt;name, damage);
}

// アイテム追加
int add_item(Player *p, int item_id) {
    if (p == NULL) return 0;  // 修正: NULLチェック
    if (p-&gt;item_count &gt;= MAX_ITEMS) return 0;  // 修正: 境界チェック

    p-&gt;items[p-&gt;item_count] = item_id;
    p-&gt;item_count++;
    return 1;
}

// アイテム使用
int use_item(Player *p, int index) {
    if (p == NULL) return 0;  // 修正: NULLチェック
    if (index &lt; 0 || index &gt;= p-&gt;item_count) return 0;  // 修正: 境界チェック

    int item_id = p-&gt;items[index];

    switch (item_id) {
        case 1:  // 薬草
            p-&gt;hp += 30;
            if (p-&gt;hp &gt; p-&gt;max_hp) p-&gt;hp = p-&gt;max_hp;  // 修正: 上限
            printf("薬草を使った！ HPが30回復！\n");
            break;
        case 2:  // 魔法の水
            p-&gt;mp += 20;
            if (p-&gt;mp &gt; p-&gt;max_mp) p-&gt;mp = p-&gt;max_mp;  // 修正: 上限
            printf("魔法の水を使った！ MPが20回復！\n");
            break;  // 修正: break追加
        default:
            printf("使えないアイテム！\n");
            return 0;
    }

    // アイテム削除（詰める）
    for (int i = index; i &lt; p-&gt;item_count - 1; i++) {  // 修正: -1
        p-&gt;items[i] = p-&gt;items[i + 1];
    }
    p-&gt;item_count--;
    return 1;
}

// レベルアップチェック
void check_level_up(Player *p, int exp) {
    if (p == NULL) return;

    p-&gt;exp += exp;  // 修正: プレイヤーの経験値として保持

    int required = p-&gt;level * 100;
    while (p-&gt;exp &gt;= required) {  // 修正: 複数レベルアップ対応
        p-&gt;exp -= required;
        p-&gt;level++;
        p-&gt;max_hp += 10;
        p-&gt;hp = p-&gt;max_hp;  // 全回復
        p-&gt;atk += 3;
        p-&gt;def += 2;
        printf("レベルアップ！ Lv.%d になった！\n", p-&gt;level);
        required = p-&gt;level * 100;
    }
}

