int battle(Player *p, Enemy *e) {
    if (p == NULL || e == NULL) return 0;  // 修正: NULLチェック

    printf("\n=== %s が現れた！ ===\n", e-&gt;name);

    while (p-&gt;hp &gt; 0 &amp;&amp; e-&gt;hp &gt; 0) {  // 修正: || を &amp;&amp; に
        printf("\n[%s] HP:%d/%d MP:%d/%d\n", 
               p-&gt;name, p-&gt;hp, p-&gt;max_hp, p-&gt;mp, p-&gt;max_mp);
        printf("[%s] HP:%d\n", e-&gt;name, e-&gt;hp);

        printf("1.攻撃 2.スキル 3.アイテム &gt; ");
        int cmd;
        if (scanf("%d", &amp;cmd) != 1) {
